        "workplace|1:1|1|p0": "ഇപ്പോഴത്തെ ചുമതലയിൽ, കമ്പനിയിലെ എല്ലാവരുടെയും ശമ്പളക്കാര്യം ഞാനാണ് നോക്കുന്നത്.",
        "workplace|1:1|1|p1": "നിങ്ങൾ ഏതു വകുപ്പിലാണ് ജോലി ചെയ്യുന്നത്, ആരുടെ കീഴിലാണ്?",
        "workplace|1:1|1|p2": "ഔദ്യോഗികമായി എന്റെ തസ്തിക സീനിയർ അനലിസ്റ്റ് ആണ്, പക്ഷേ എന്റെ ജോലികൾ എല്ലാ ആഴ്ചയും മാറും.",
        "workplace|1:1|1|p3": "ആറു പേരുള്ള ഒരു ടീമിന്റെ മേൽനോട്ടം വഹിക്കുന്നതും ക്ലയന്റ് കോളുകളിൽ മിക്കതും കൈകാര്യം ചെയ്യുന്നതും ഞാനാണ്.",
        "workplace|1:1|1|p4": "സാധാരണ ഒരു ദിവസം, ഉച്ചഭക്ഷണത്തിനു മുമ്പ് അടിയന്തര ജോലികൾ തീർത്ത് ബാക്കിയുള്ളവ പ്ലാൻ ചെയ്യും.",
