        "workplace|1:1|2|w5": "സ്പെഷ്യലൈസ് ചെയ്യുക",
        "workplace|1:1|3|p0": "ഞങ്ങളുടെ ആസ്ഥാനം ബെംഗളൂരുവിലാണ്, പക്ഷേ ജീവനക്കാരിൽ മിക്കവരും ഹുബ്ബള്ളിയിലാണ്.",
        "workplace|1:1|3|p1": "ക്ലിനിക്കുകൾക്കായി ബില്ലിങ് സോഫ്റ്റ്വെയർ ഉണ്ടാക്കുന്ന ഒരു ചെറിയ സ്റ്റാർട്ടപ്പാണ് ഞങ്ങൾ.",
        "workplace|1:1|3|p2": "മൈസൂരുവിനടുത്തുള്ള ഞങ്ങളുടെ പ്ലാന്റ് ഇന്ത്യയിലെ മിക്ക ടൂവീലർ ബ്രാൻഡുകൾക്കും ബ്രേക്ക് പാർട്ടുകൾ നിർമ്മിക്കുന്നു.",
        "workplace|1:1|3|p3": "ഗ്രാമീണ ആരോഗ്യ രംഗത്തെ വൈദഗ്ധ്യമാണ് ഞങ്ങളെ വ്യത്യസ്തരാക്കുന്നത്.",
        "workplace|1:1|3|p4": "ചെറിയ പട്ടണങ്ങളിലെ കടകളെ ഓൺലൈൻ വിൽപ്പന തുടങ്ങാൻ സഹായിക്കുന്നതിലാണ് ഞങ്ങൾ സ്പെഷ്യലൈസ് ചെയ്യുന്നത്.",
        "workplace|1:1|4|title": "നിനക്ക് ശരിക്കും എന്താണ് ജോലി?",
        "workplace|1:1|4|text": "ധാർവാഡിലെ ഒരു കുടുംബ കല്യാണത്തിൽ വെച്ച്, ജോലിയിൽ ശരിക്കും എന്താണ് ചെയ്യുന്നതെന്ന് നിഖിലിന്റെ അമ്മാവൻ ചോദിച്ചു. കർഷകർക്കായി മണ്ണ് സെൻസറുകൾ ഉണ്ടാക്കുന്ന ഒരു സ്റ്റാർട്ടപ്പിലാണ് താൻ ജോലി ചെയ്യുന്നതെന്ന് നിഖിൽ വിശദീകരിച്ചു. കമ്പനിയുടെ ആസ്ഥാനം ബെംഗളൂരുവിലാണ്, പക്ഷേ സെൻസറുകൾ നിർമ്മിക്കുന്നത് ഹുബ്ബള്ളിക്കടുത്തുള്ള ഒരു ചെറിയ ഫാക്ടറിയിലാണ്. അവന്റെ തസ്തിക പ്രോഡക്ട് എഞ്ചിനീയർ ആണ്; ടെസ്റ്റിങ് വകുപ്പിലാണ് അവൻ. കർഷകരുടെ അടുത്തേക്ക് അയയ്ക്കുന്നതിനു മുമ്പ് ഓരോ പുതിയ സെൻസറും പരിശോധിക്കുക എന്നതാണ് അവന്റെ പ്രധാന ജോലി. രണ്ട് ജൂനിയർ എഞ്ചിനീയർമാരുടെ മേൽനോട്ടം വഹിക്കുന്നതും ഫാക്ടറി ടീമിന്റെ ചോദ്യങ്ങൾ കൈകാര്യം ചെയ്യുന്നതും അവനാണ്. കമ്പനിയിൽ ഒരുപാട് ജീവനക്കാർ ഉണ്ടാകുമല്ലോ എന്ന് അമ്മാവൻ ചിരിച്ചുകൊണ്ട് പറഞ്ഞു. നാൽപ്പതു പേർ മാത്രമേയുള്ളൂ, പക്ഷേ ഓരോരുത്തർക്കും ശരിക്കുള്ള വൈദഗ്ധ്യമുണ്ടെന്ന് നിഖിൽ ചിരിച്ചുകൊണ്ട് മറുപടി നൽകി.",
        "workplace|1:1|4|q0": "നിഖിലിന്റെ കമ്പനി എന്താണ് ഉണ്ടാക്കുന്നത്?",
