        "workplace|1:1|5|scenario": "ബെംഗളൂരുവിലെ ഒരു ബിസിനസ് പരിപാടിയിൽ വെച്ച് അനന്യയും ഫർഹാനും ആദ്യമായി കണ്ടുമുട്ടുന്നു; അവർ തങ്ങളുടെ ജോലിയെക്കുറിച്ച് സംസാരിക്കുന്നു.",
        "workplace|1:1|5|l0": "ഹായ്, ഞാൻ സഹ്യാദ്രി ലോജിസ്റ്റിക്സിലെ ഫർഹാൻ. എന്താണ് ഈ പരിപാടിക്ക് വന്നത്?",
        "workplace|1:1|5|l1": "കണ്ടതിൽ സന്തോഷം. ഞാൻ അനന്യ. ഒരു ഫിൻടെക് സ്റ്റാർട്ടപ്പിലെ കസ്റ്റമർ സപ്പോർട്ട് ടീമിന്റെ മേധാവിയാണ്.",
        "workplace|1:1|5|l2": "കൊള്ളാമല്ലോ. നിങ്ങളുടെ കമ്പനി കൃത്യമായി എന്താണ് ചെയ്യുന്നത്?",
        "workplace|1:1|5|l3": "ചെറിയ കടക്കാർക്ക് കണക്കുകൾ സൂക്ഷിക്കാനും ഡിജിറ്റൽ പേയ്മെന്റുകൾ സ്വീകരിക്കാനും സഹായിക്കുന്ന ഒരു ആപ്പ് ഞങ്ങൾ ഉണ്ടാക്കിയിട്ടുണ്ട്.",
        "workplace|1:1|5|l4": "നിങ്ങളുടെ ഒരു സാധാരണ ദിവസം എങ്ങനെയാണ്?",
        "workplace|1:1|5|l5": "ടീമുമായി ഒരു ചെറിയ കോളോടെയാണ് തുടങ്ങുന്നത്; പിന്നെ ബുദ്ധിമുട്ടുള്ള പരാതികൾ ഞാൻ തന്നെ കൈകാര്യം ചെയ്യും.",
        "workplace|1:1|5|l6": "നല്ല ഭാരമുള്ള ജോലിയാണല്ലോ. നിങ്ങളുടെ ടീമിൽ എത്ര പേരുണ്ട്?",
        "workplace|1:1|5|l7": "രണ്ടു ഷിഫ്റ്റുകളിലായി പന്ത്രണ്ടു പേർ. നിങ്ങളോ? നിങ്ങളുടെ ചുമതല എന്താണ്?",
        "workplace|1:1|5|l8": "ഞാൻ ഒരു റൂട്ട് പ്ലാനറാണ്. ചുരുക്കിപ്പറഞ്ഞാൽ, ഞങ്ങളുടെ ട്രക്കുകൾ ഏറ്റവും വേഗമേറിയതും ചെലവു കുറഞ്ഞതുമായ റോഡുകളിലൂടെ പോകുന്നുവെന്ന് ഞാൻ ഉറപ്പാക്കും.",
        "workplace|1:1|5|l9": "അപ്പോൾ എന്റെ പാഴ്സലുകൾ സമയത്ത് എത്തുന്നത് നിങ്ങൾ കാരണമാണ്! നമുക്ക് ബന്ധം നിലനിർത്താം.",
        "workplace|1:1|5|q0": "അനന്യയുടെ കമ്പനി എന്താണ് ഉണ്ടാക്കിയിരിക്കുന്നത്?",
        "workplace|1:1|5|q0o0": "ചെറിയ കടക്കാർക്കുള്ള ഒരു ആപ്പ്",
