        "workplace|2:1|0|w5": "പങ്കാളി",
        "workplace|2:1|1|p0": "സംസാരിക്കാത്തപ്പോൾ എല്ലാവരും ദയവായി മ്യൂട്ട് ചെയ്യാമോ?",
        "workplace|2:1|1|p1": "മീറ്റിങ് ലിങ്ക് ഞാൻ ഇപ്പോൾ ടീം ചാറ്റിൽ അയച്ചിട്ടുണ്ട്.",
        "workplace|2:1|1|p2": "രവീ, നിങ്ങളുടെ വെബ്ക്യാം ഓഫാണ്; ഒരു മിനിറ്റ് ഒന്ന് ഓണാക്കാമോ?",
        "workplace|2:1|1|p3": "വെയിറ്റിങ് റൂമിൽ നിന്ന് പങ്കാളികളെ അകത്തേക്ക് കയറ്റാൻ ഹോസ്റ്റിനു മാത്രമേ കഴിയൂ.",
        "workplace|2:1|1|p4": "നിങ്ങളുടെ പിന്നിലെ ട്രാഫിക് ശബ്ദം കേൾക്കാതിരിക്കാൻ ദയവായി ഒരു ഹെഡ്സെറ്റ് വെക്കൂ.",
        "workplace|2:1|2|w0": "സ്ഥിരതയില്ലാത്ത",
