        "workplace|2:1|2|w3": "പ്രതിധ്വനി",
        "workplace|2:1|2|w4": "റെക്കോർഡിങ്",
        "workplace|2:1|2|w5": "ഫോളോ-അപ്പ്",
        "workplace|2:1|3|p0": "ക്ഷമിക്കണം, എന്റെ കണക്ഷൻ സ്ഥിരതയില്ലാത്തതാണ്; ഞാൻ വീഡിയോ ഓഫാക്കാം.",
        "workplace|2:1|3|p1": "കുറച്ചു സെക്കൻഡിന്റെ കാലതാമസമുണ്ട്, അതുകൊണ്ട് നമുക്ക് ഒരുമിച്ച് സംസാരിക്കാതിരിക്കാം.",
        "workplace|2:1|3|p2": "നിങ്ങളുടെ സ്ക്രീൻ ഫ്രീസായി; ഒന്നുകൂടി ഷെയർ ചെയ്യാമോ?",
        "workplace|2:1|3|p3": "ഒരു പ്രതിധ്വനി കേൾക്കുന്നുണ്ട്; ആരുടെയോ ലാപ്ടോപ്പ് സ്പീക്കർ മൈക്കിന് വളരെ അടുത്താണ്.",
        "workplace|2:1|3|p4": "ഇന്ന് വൈകുന്നേരത്തിനകം റെക്കോർഡിങ്ങും ഒരു ചെറിയ ഫോളോ-അപ്പ് ഇമെയിലും ഞാൻ അയയ്ക്കാം.",
        "workplace|2:1|4|title": "ഇടയ്ക്കിടെ ഫ്രീസായ കോൾ",
        "workplace|2:1|4|text": "എല്ലാ തിങ്കളാഴ്ചയും മൈസൂരുവിലെ തന്റെ ടീമും പുണെയിലെ സെയിൽസ് ടീമും തമ്മിലുള്ള വീഡിയോ കോളിന്റെ ഹോസ്റ്റ് ദീപയാണ്. കഴിഞ്ഞ ആഴ്ച കോൾ മോശമായാണ് തുടങ്ങിയത്. പന്ത്രണ്ട് പങ്കാളികൾ ചേർന്നു, പക്ഷേ അവരിൽ മൂന്നു പേർക്ക് ലിങ്ക് തുറക്കാൻ കഴിഞ്ഞില്ല. പിന്നെ വലിയ പ്രതിധ്വനി ഉണ്ടായി, കാരണം സുരേഷ് ഒരേ സമയം ലാപ്ടോപ്പിൽ നിന്നും ഫോണിൽ നിന്നും ചേർന്നിരുന്നു. ദീപ സ്ക്രീൻ ഷെയർ ചെയ്യാൻ തുടങ്ങിയപ്പോൾ അത് ഫ്രീസായി; അവളുടെ ശബ്ദം വലിയ കാലതാമസത്തോടെയാണ് പുണെയിൽ എത്തിയത്. എല്ലാവരോടും മ്യൂട്ട് ചെയ്യാനും വെബ്ക്യാം ഓഫാക്കാനും ഹെഡ്സെറ്റ് ഉപയോഗിക്കാനും അവൾ ശാന്തമായി ആവശ്യപ്പെട്ടു. കണക്ഷൻ മെച്ചപ്പെട്ടു; മീറ്റിങ് പത്തു മിനിറ്റ് മാത്രം വൈകി അവസാനിച്ചു. അന്നു വൈകുന്നേരം, ഓരോ തീരുമാനവും ഡെഡ്ലൈനും വ്യക്തമായി പട്ടികപ്പെടുത്തിയ ഒരു ഫോളോ-അപ്പ് ഇമെയിലും റെക്കോർഡിങ്ങും ദീപ അയച്ചു.",
        "workplace|2:1|4|q0": "വലിയ പ്രതിധ്വനി ഉണ്ടായത് എന്തുകൊണ്ടാണ്?",
        "workplace|2:1|4|q0o0": "സുരേഷ് ഒരേ സമയം രണ്ട് ഉപകരണങ്ങളിൽ നിന്ന് ചേർന്നു",
        "workplace|2:1|4|q0o1": "ദീപയുടെ ഹെഡ്സെറ്റ് കേടായിരുന്നു",
        "workplace|2:1|4|q0o2": "പുണെ ഓഫീസിൽ വലിയ ബഹളമായിരുന്നു",
        "workplace|2:1|4|q0o3": "ലിങ്ക് തെറ്റായിരുന്നു",
        "workplace|2:1|4|q1": "ദീപ എല്ലാവരോടും എന്താണ് ചെയ്യാൻ ആവശ്യപ്പെട്ടത്?",
        "workplace|2:1|4|q1o0": "മ്യൂട്ട് ചെയ്യാനും വെബ്ക്യാം ഓഫാക്കാനും ഹെഡ്സെറ്റ് ഉപയോഗിക്കാനും",
