        "workplace|2:1|4|q2o3": "സുരേഷിന് ഒരു പുതിയ ഹെഡ്സെറ്റ്",
        "workplace|2:1|5|title": "എന്റെ സ്ക്രീൻ കാണാമോ?",
        "workplace|2:1|5|scenario": "ഹുബ്ബള്ളിയിലെ വീട്ടിൽ നിന്ന് കാർത്തിക് ഒരു ഓൺലൈൻ പ്രോജക്ട് മീറ്റിങ്ങിൽ ചേരുന്നു. ഹോസ്റ്റായ മീര ശബ്ദത്തിലും സ്ക്രീനിലും അവനെ സഹായിക്കുന്നു.",
        "workplace|2:1|5|l0": "ഹായ് കാർത്തിക്, ഞങ്ങൾക്ക് നിങ്ങളെ കാണാം, പക്ഷേ നിങ്ങൾ മ്യൂട്ടിലാണ്.",
        "workplace|2:1|5|l1": "ക്ഷമിക്കണം. ഇപ്പോൾ കേൾക്കാമോ?",
        "workplace|2:1|5|l2": "ഉവ്വ്, നന്നായി കേൾക്കാം. സ്ക്രീൻ ഷെയർ ചെയ്ത് ടെസ്റ്റ് ഫലങ്ങൾ ഒന്ന് വിശദീകരിക്കാമോ?",
        "workplace|2:1|5|l3": "തീർച്ചയായും, ഒരു സെക്കൻഡ്. എല്ലാവർക്കും എന്റെ സ്ക്രീൻ കാണാമോ?",
        "workplace|2:1|5|l4": "ഒരു സ്പ്രെഡ്ഷീറ്റ് കാണാം, പക്ഷേ അത് ഫ്രീസായെന്ന് തോന്നുന്നു.",
        "workplace|2:1|5|l5": "എന്റെ കണക്ഷൻ ഇടയ്ക്കിടെ പോകുന്നു. ഞാൻ വീഡിയോ ഓഫാക്കി വീണ്ടും നോക്കട്ടെ.",
        "workplace|2:1|5|l6": "ഇപ്പോൾ ഒരുപാട് ഭേദമാണ്, നീങ്ങുന്നുണ്ട്. തുടർന്നോളൂ.",
        "workplace|2:1|5|l7": "നന്ദി. കാണുന്നതുപോലെ, ഈ ആഴ്ചത്തെ ടെസ്റ്റുകളിൽ തൊണ്ണൂറു ശതമാനവും വിജയിച്ചു.",
        "workplace|2:1|5|l8": "നല്ല ജോലി. പുണെ ടീമിന് പിന്നീട് കാണാൻ വേണ്ടി ഞാൻ ഇത് റെക്കോർഡ് ചെയ്യുന്നുണ്ട്.",
        "workplace|2:1|5|l9": "നന്നായി. കോൾ കഴിഞ്ഞ് പരാജയപ്പെട്ട ടെസ്റ്റുകളുമായി ഒരു ചെറിയ ഫോളോ-അപ്പും ഞാൻ അയയ്ക്കാം.",
