        "workplace|3:1|0|w5": "കണക്ക്",
        "workplace|3:1|1|p0": "ഇന്ന് നമ്മൾ എന്തൊക്കെ ചർച്ച ചെയ്യുമെന്നതിന്റെ ഒരു ചെറിയ അവലോകനത്തോടെ തുടങ്ങാം.",
        "workplace|3:1|1|p1": "ഈ സ്ലൈഡിൽ കാണുന്നതുപോലെ, മാർച്ചിനു ശേഷം വിൽപ്പന ഇരട്ടിയായി.",
        "workplace|3:1|1|p2": "രൂപരേഖ ലളിതമാക്കിയിട്ടുണ്ട്: പ്രശ്നം, പരിഹാരം, ചെലവ്, സമയക്രമം.",
        "workplace|3:1|1|p3": "കഴിഞ്ഞ രണ്ടു വർഷത്തെ ഞങ്ങളുടെ മാസക്കണക്കുകളാണ് ഈ ചാർട്ടിൽ കാണിക്കുന്നത്.",
        "workplace|3:1|1|p4": "ഒരു കണക്ക് പ്രത്യേകം എടുത്തുപറയാൻ ആഗ്രഹിക്കുന്നു: ഞങ്ങളുടെ ചെലവ് പന്ത്രണ്ടു ശതമാനം കുറഞ്ഞു.",
        "workplace|3:1|2|w0": "പ്രൊജക്ടർ",
        "workplace|3:1|2|w1": "റിഹേഴ്സൽ ചെയ്യുക",
        "workplace|3:1|2|w2": "അച്ചടിച്ച കുറിപ്പ്",
        "workplace|3:1|2|w3": "വ്യക്തമാക്കുക",
        "workplace|3:1|2|w4": "ഉപസംഹരിക്കുക",
        "workplace|3:1|2|w5": "ചുരുക്കിപ്പറയുക",
        "workplace|3:1|3|p0": "ആരെങ്കിലും പ്രൊജക്ടർ ഒന്ന് നോക്കാമോ? സ്ലൈഡുകൾ വളരെ ഇരുണ്ടതായി കാണുന്നു.",
        "workplace|3:1|3|p1": "മുഴുവൻ അവതരണവും ഞാൻ രണ്ടു തവണ റിഹേഴ്സൽ ചെയ്തു, അതുകൊണ്ട് എത്ര സമയമെടുക്കുമെന്ന് കൃത്യമായി അറിയാം.",
        "workplace|3:1|3|p2": "എല്ലാ കണക്കുകളുമുള്ള ഒരു അച്ചടിച്ച കുറിപ്പുണ്ട്, അതുകൊണ്ട് നോട്ട് എഴുതേണ്ടതില്ല.",
        "workplace|3:1|3|p3": "നല്ല ചോദ്യം; മൊത്തം ചെലവ് എന്നതുകൊണ്ട് ഞാൻ എന്താണ് ഉദ്ദേശിച്ചതെന്ന് വ്യക്തമാക്കാം.",
        "workplace|3:1|3|p4": "ഉപസംഹരിക്കാൻ, മൂന്നു പ്രധാന കാര്യങ്ങൾ ഒരു മിനിറ്റിൽ ചുരുക്കിപ്പറയാം.",
        "workplace|3:1|4|title": "രേഖയുടെ വലിയ ദിവസം",
        "workplace|3:1|4|text": "ഹുബ്ബള്ളിയിലെ മാർക്കറ്റിങ് എക്സിക്യൂട്ടീവായ രേഖയ്ക്ക് കമ്പനിയുടെ ഡയറക്ടർമാർക്കു മുന്നിൽ വാർഷിക ഫലങ്ങൾ അവതരിപ്പിക്കണമായിരുന്നു. അവൾ ലളിതമായ ഒരു രൂപരേഖയും, ഓരോന്നിലും വ്യക്തമായ ഒരു ചാർട്ടുള്ള എട്ടു സ്ലൈഡുകളും മാത്രം തയ്യാറാക്കി. തലേന്ന് രാത്രി, സഹോദരിയുടെ മുന്നിൽ അവൾ മുഴുവൻ അവതരണവും മൂന്നു തവണ റിഹേഴ്സൽ ചെയ്തു. അന്ന്, അവൾ തുടങ്ങുന്നതിന് അഞ്ചു മിനിറ്റ് മുമ്പ് മീറ്റിങ് റൂമിലെ പ്രൊജക്ടർ പ്രവർത്തിക്കാതായി. ഭാഗ്യത്തിന്, എല്ലാ പ്രധാന കണക്കുകളുമുള്ള കുറിപ്പുകൾ രേഖ അച്ചടിച്ചു വെച്ചിരുന്നു. ചെറിയ ഒരു അവലോകനത്തോടെ തുടങ്ങി, ഡെലിവറി ചെലവ് എത്ര കുറഞ്ഞുവെന്ന് അവൾ എടുത്തുപറഞ്ഞു. ബെളഗാവിയിലെ പുതിയ കടയെക്കുറിച്ച് ഒരു ഡയറക്ടർ ചോദിച്ചപ്പോൾ, അവൾ ശാന്തമായി കണക്കുകൾ വ്യക്തമാക്കി. മൂന്നു പ്രധാന കാര്യങ്ങൾ ചുരുക്കിപ്പറഞ്ഞ് അവൾ ഉപസംഹരിച്ചു; ഇത്രയും വ്യക്തമായി അവതരിപ്പിച്ചതിന് ഡയറക്ടർമാർ അവളോട് നന്ദി പറഞ്ഞു.",
        "workplace|3:1|4|q0": "രേഖ എത്ര സ്ലൈഡുകൾ തയ്യാറാക്കി?",
