        "workplace|3:1|5|scenario": "പുണെയിലെ ഓഫീസിൽ വെച്ച് സഞ്ജയ് തന്റെ മാനേജരായ ലക്ഷ്മിയോടൊപ്പം ഒരു ക്ലയന്റ് അവതരണം റിഹേഴ്സൽ ചെയ്യുന്നു.",
        "workplace|3:1|5|l0": "ശരി സഞ്ജയ്, ഞാനാണ് ക്ലയന്റ് എന്ന് കരുതൂ. റെഡിയാകുമ്പോൾ തുടങ്ങിക്കോളൂ.",
        "workplace|3:1|5|l1": "എല്ലാവർക്കും നമസ്കാരം, ഞങ്ങളെ ക്ഷണിച്ചതിന് നന്ദി. നിങ്ങളുടെ പുതിയ വെബ്സൈറ്റിനായുള്ള ഞങ്ങളുടെ പ്ലാൻ ഇന്ന് ഞാൻ വിശദീകരിക്കാം.",
        "workplace|3:1|5|l2": "നല്ല തുടക്കം. അവതരണം എങ്ങനെ ക്രമീകരിക്കും?",
        "workplace|3:1|5|l3": "മൂന്നു കാര്യങ്ങൾ പറയും: ഞങ്ങൾ കണ്ടെത്തിയത്, ഞങ്ങൾ നിർദ്ദേശിക്കുന്നത്, അതിന് വരുന്ന ചെലവ്.",
        "workplace|3:1|5|l4": "നല്ല വ്യക്തമാണ്. പകുതിക്കു വെച്ച് ക്ലയന്റ് ഒരു ചോദ്യവുമായി ഇടപെട്ടാലോ?",
        "workplace|3:1|5|l5": "ഞാൻ നന്ദി പറഞ്ഞ്, ചോദ്യം കുറിച്ചെടുത്ത്, അവസാനം അതിലേക്ക് വരാമെന്ന് പറയും.",
        "workplace|3:1|5|l6": "കൊള്ളാം. അവസാനത്തെ സ്ലൈഡിൽ എന്താണ്?",
        "workplace|3:1|5|l7": "മൂന്നു കാര്യങ്ങളുടെ ചുരുക്കവും വ്യക്തമായ അടുത്ത പടിയും: അടുത്ത വെള്ളിയാഴ്ച ഒരു മീറ്റിങ്.",
        "workplace|3:1|5|l8": "ഗംഭീരം. കുറച്ചുകൂടി പതുക്കെ സംസാരിക്കൂ, സ്ക്രീനിലല്ല, കേൾവിക്കാരെ നോക്കൂ.",
        "workplace|3:1|5|l9": "നന്ദി ലക്ഷ്മി. ഇന്നു രാത്രി ഒന്നുകൂടി റിഹേഴ്സൽ ചെയ്യാം.",
        "workplace|3:1|5|q0": "സഞ്ജയ് എന്താണ് അവതരിപ്പിക്കുന്നത്?",
        "workplace|3:1|5|q0o0": "ഒരു ക്ലയന്റിന്റെ പുതിയ വെബ്സൈറ്റിനുള്ള പ്ലാൻ",
