        "workplace|4:1|1|p0": "ഞങ്ങൾ എന്തെങ്കിലും നിർദ്ദേശിക്കുന്നതിനു മുമ്പ്, നിങ്ങളുടെ ആവശ്യങ്ങളെക്കുറിച്ച് കുറച്ചുകൂടി പറയാമോ?",
        "workplace|4:1|1|p1": "വ്യാഴാഴ്ചയ്ക്കകം വിശദമായ ഒരു പ്രൊപ്പോസലും ക്വട്ടേഷനും ഞങ്ങൾ അയയ്ക്കാം.",
        "workplace|4:1|1|p2": "ഏകദേശ സമയക്രമം ആറ് ആഴ്ചയാണ്, പക്ഷേ സൈറ്റ് സന്ദർശിച്ച ശേഷം ഞാൻ ഉറപ്പിച്ചു പറയാം.",
        "workplace|4:1|1|p3": "ഏതു പ്ലാനാണ് നിങ്ങൾക്ക് യോജിച്ചതെന്ന് തീരുമാനിക്കാൻ ഒരു ചെറിയ ഡെമോ സഹായിക്കുമോ?",
