        "workplace|4:1|3|p0": "നിങ്ങളുടെ ഓർഡർ തിങ്കളാഴ്ച ഞങ്ങളുടെ പുണെ വെയർഹൗസിൽ നിന്ന് അയച്ചുകൊടുക്കും.",
        "workplace|4:1|3|p1": "ഇൻവോയ്സിൽ തെറ്റായ തുകയാണ് കാണിക്കുന്നത്, അതുകൊണ്ട് അത് തിരുത്താൻ ഞാൻ അക്കൗണ്ട്സിനോട് പറയാം.",
        "workplace|4:1|3|p2": "നിങ്ങളുടെ നിരാശ എനിക്ക് മനസ്സിലാകുന്നുണ്ട്; ഇന്നു തന്നെ ഇത് എന്റെ മാനേജർക്ക് കൈമാറാം.",
        "workplace|4:1|3|p3": "വൈകിയതിന് പരിഹാരമായി, ഇത്തവണ ഡെലിവറി ചാർജ് ഞങ്ങൾ ഒഴിവാക്കുന്നു.",
