        "workplace|4:1|4|title": "ഒരിക്കലും എത്താത്ത മെനു കാർഡുകൾ",
        "workplace|4:1|4|text": "ബെംഗളൂരുവിലെ ഒരു പ്രിന്റിങ് കമ്പനിയിൽ ക്ലയന്റ് അക്കൗണ്ടുകൾ കൈകാര്യം ചെയ്യുന്നത് ഇമ്രാനാണ്. ഒരു തിങ്കളാഴ്ച, മൈസൂരുവിൽ ഹോട്ടൽ നടത്തുന്ന ഷെട്ടി മാഡം വളരെ ദേഷ്യത്തോടെ അവനെ വിളിച്ചു. ഒരാഴ്ചയ്ക്കുള്ളിൽ ഡെലിവറി എന്ന് ക്വട്ടേഷനിൽ പറഞ്ഞിരുന്നെങ്കിലും അവരുടെ പുതിയ മെനു കാർഡുകൾ എത്തിയിരുന്നില്ല. ഇമ്രാൻ ഇടയ്ക്കു കയറാതെ മുഴുവൻ കേട്ടു; പിന്നെ ശരിയായി മനസ്സിലായെന്ന് ഉറപ്പാക്കാൻ അവരുടെ ആവശ്യങ്ങൾ ആവർത്തിച്ചു പറഞ്ഞു. ഇൻവോയ്സിലെ ഒരു തെറ്റു കാരണം ഓർഡർ അയച്ചിട്ടേയില്ലെന്ന് അവൻ കണ്ടെത്തി. അവൻ പ്രശ്നം മാനേജർക്ക് കൈമാറി, അന്ന് ഉച്ചയ്ക്കു തന്നെ ഒരു കൊറിയർ ഏർപ്പാടാക്കി. വൈകിയതിന് പരിഹാരമായി കമ്പനി ബില്ലിൽ നിന്ന് പത്തു ശതമാനം കുറച്ചു. ഇനിയുള്ള ഓർഡറുകൾ താൻ നേരിട്ട് പരിശോധിക്കുമെന്ന് ഇമ്രാൻ ഉറപ്പു നൽകി; അവർ കമ്പനിയുമായുള്ള ബന്ധം തുടർന്നു.",
        "workplace|4:1|4|q0": "ഷെട്ടി മാഡം എന്തിനാണ് ദേഷ്യപ്പെട്ടത്?",
        "workplace|4:1|4|q0o0": "അവരുടെ മെനു കാർഡുകൾ എത്തിയിരുന്നില്ല",
        "workplace|4:1|4|q0o1": "കാർഡുകളിൽ അക്ഷരത്തെറ്റുകളുണ്ടായിരുന്നു",
