        "workplace|4:1|5|l3": "ലളിതവും സൗകര്യപ്രദവുമായ എന്തെങ്കിലും. ഞങ്ങളുടെ ബജറ്റ് ഏകദേശം എട്ടു ലക്ഷം രൂപയാണ്.",
