        "workplace|5:1|3|p1": "ഞാൻ ഇല്ലാത്തപ്പോൾ എന്റെ കോളുകൾ പകരം നോക്കാമെന്ന് പ്രിയ സമ്മതിച്ചിട്ടുണ്ട്.",
        "workplace|5:1|3|p2": "ഒന്നും വിട്ടുപോകാതിരിക്കാൻ വ്യാഴാഴ്ച ഞാൻ ചുമതല ശരിയായി കൈമാറും.",
        "workplace|5:1|3|p3": "നമ്മുടെ റിവ്യൂ അടുത്ത ആഴ്ചയിലേക്ക് മാറ്റാമോ? തിങ്കളാഴ്ച ഞാൻ അവധിയിലാണ്.",
        "workplace|5:1|3|p4": "കുറഞ്ഞത് ഒരാഴ്ച മുൻകൂട്ടി ചോദിക്കുന്നിടത്തോളം ഞങ്ങളുടെ മാനേജർക്ക് അയവുള്ള സമീപനമാണ്.",
        "workplace|5:1|4|title": "ഉഡുപ്പിയിലെ ഒരു കല്യാണം",
        "workplace|5:1|4|text": "ബെംഗളൂരുവിലെ ഒരു ബാങ്കിന്റെ ഹെഡ് ഓഫീസിൽ പേയ്മെന്റ്സ് ടീമിലാണ് സൗമ്യ ജോലി ചെയ്യുന്നത്. ഉഡുപ്പിയിൽ അവളുടെ കസിന്റെ കല്യാണം മാർച്ചിലെ അവസാന ആഴ്ചയിലായിരുന്നു, വർഷത്തിലെ ഏറ്റവും തിരക്കുള്ള സമയം. ബാക്കിയുള്ള അവധി നോക്കിയപ്പോൾ ഇനിയും ഒമ്പതു ദിവസമുണ്ടെന്ന് അവൾ കണ്ടു. മൂന്നാഴ്ച മുൻകൂട്ടി, അവൾ മാനേജരായ ഭട്ട് സാറിനോട് നാലു ദിവസത്തെ അവധി ചോദിച്ച്, കാരണം മര്യാദയോടെ വിശദീകരിച്ചു. കല്യാണത്തിന്റെ പിറ്റേന്ന് വീട്ടിലിരുന്ന് ജോലി ചെയ്യാമെന്നും അവൾ പറഞ്ഞു. ഭട്ട് സാർ അയവുള്ളയാളായിരുന്നു, പക്ഷേ മാസാവസാന റിപ്പോർട്ടുകൾ ആര് നോക്കുമെന്ന് അദ്ദേഹം ചോദിച്ചു. സഹപ്രവർത്തകനായ രാകേഷുമായി സൗമ്യ രണ്ടു ഷിഫ്റ്റുകൾ വെച്ചുമാറി; പോകുന്നതിനു മുമ്പ് ചുമതല മുഴുവൻ കൈമാറാമെന്നും വാക്കു കൊടുത്തു. അവളുടെ പ്ലാനിൽ സന്തോഷിച്ച ഭട്ട് സാർ അന്ന് ഉച്ചയ്ക്കു തന്നെ അവധി അംഗീകരിച്ചു.",
        "workplace|5:1|4|q0": "സൗമ്യയ്ക്ക് എന്തിനാണ് അവധി വേണ്ടിയിരുന്നത്?",
        "workplace|5:1|4|q0o0": "ഉഡുപ്പിയിലെ കസിന്റെ കല്യാണത്തിന്",
        "workplace|5:1|4|q0o1": "അവൾക്ക് അസുഖമായിരുന്നതുകൊണ്ട്",
