        "workplace|5:1|5|scenario": "അമ്മയ്ക്ക് സുഖമില്ലാത്തതിനാൽ അരുൺ അതിരാവിലെ തന്റെ ടീം ലീഡായ ശാലിനിയെ വിളിക്കുന്നു.",
        "workplace|5:1|5|l0": "നമസ്കാരം ശാലിനി. ഇത്ര നേരത്തെ വിളിച്ചതിന് ക്ഷമിക്കണം. ഒരു മിനിറ്റ് സംസാരിക്കാമോ?",
        "workplace|5:1|5|l1": "തീർച്ചയായും അരുൺ. എല്ലാം ശരിയല്ലേ?",
        "workplace|5:1|5|l2": "അത്ര ശരിയല്ല. ഇന്നലെ രാത്രി അമ്മ വീണു; ചില ടെസ്റ്റുകൾക്കായി ആശുപത്രിയിൽ കൊണ്ടുപോകണം.",
        "workplace|5:1|5|l3": "അയ്യോ, കേട്ടതിൽ വിഷമമുണ്ട്. അമ്മയെ നന്നായി നോക്കൂ. ദിവസം മുഴുവൻ വേണ്ടിവരുമോ?",
        "workplace|5:1|5|l4": "വേണ്ടിവരുമെന്ന് തോന്നുന്നു. ഇന്ന് അവധി എടുക്കണം, നാളെ ഒരുപക്ഷേ വീട്ടിലിരുന്ന് ജോലി ചെയ്യാം.",
        "workplace|5:1|5|l5": "കുഴപ്പമില്ല. മൂന്നു മണിക്കുള്ള ക്ലയന്റ് കോളിന്റെ കാര്യമോ?",
        "workplace|5:1|5|l6": "ദീപക്കിന് പ്രോജക്ട് നന്നായി അറിയാം. ഞാൻ അവനോട് ചോദിച്ചുകഴിഞ്ഞു; അത് സന്തോഷത്തോടെ നോക്കിക്കോളാമെന്ന് അവൻ പറഞ്ഞു.",
        "workplace|5:1|5|l7": "നല്ലത്. നിങ്ങളുടെ നോട്ടുകൾ അവന് അയച്ചുകൊടുക്കൂ; പറ്റുമ്പോൾ പോർട്ടലിൽ അവധിക്ക് അപേക്ഷിക്കുകയും ചെയ്യൂ.",
        "workplace|5:1|5|l8": "ഒരു മണിക്കൂറിനുള്ളിൽ ചെയ്യാം. മനസ്സിലാക്കിയതിന് നന്ദി, ശാലിനി.",
        "workplace|5:1|5|l9": "സാരമില്ല. അമ്മയ്ക്ക് വേഗം സുഖമാകട്ടെ.",
        "workplace|5:1|5|q0": "അരുണിന് എന്തിനാണ് അവധി വേണ്ടത്?",
