        "workplace|6:1|1|p1": "ദേഷ്യപ്പെട്ട ഉപഭോക്താക്കളെ നിങ്ങൾ ശാന്തമായി കൈകാര്യം ചെയ്യുന്ന രീതിയാണ് നിങ്ങളുടെ ഏറ്റവും വലിയ കരുത്ത്.",
        "workplace|6:1|1|p2": "ഇന്നലത്തെ അവതരണത്തെക്കുറിച്ച് ചില ക്രിയാത്മകമായ അഭിപ്രായങ്ങൾ പറയട്ടെ?",
        "workplace|6:1|1|p3": "എന്റെ സ്വയം വിലയിരുത്തലിൽ, സമയം കൈകാര്യം ചെയ്യുന്നത് ഒരു ബലഹീനതയായി ഞാൻ എഴുതിയിട്ടുണ്ട്.",
        "workplace|6:1|1|p4": "മൈസൂരു ശാഖ കൃത്യസമയത്ത് തുടങ്ങിയത് ഞങ്ങളുടെ ടീമിന് ഒരു യഥാർത്ഥ നാഴികക്കല്ലായിരുന്നു.",
        "workplace|6:1|2|w0": "വഴികാട്ടി",
        "workplace|6:1|2|w1": "കഴിവുകൾ മെച്ചപ്പെടുത്തുക",
